export type ProductCategory = "bra" | "panty" | "print" | "brief" | "trunk" | "top";
export type Gender = "Women" | "Men";

export type Product = {
  id: string;
  name: string;
  colour: string;
  category: ProductCategory;
  gender: Gender;
  /** Representative fabric colour (swatches, glows). */
  hex: string;
  image: string;
  /** Natural size of the WebP — lets the browser reserve space. */
  w: number;
  h: number;
};

export const CATEGORIES: { id: ProductCategory; label: string; gender: Gender }[] = [
  { id: "bra", label: "Bras", gender: "Women" },
  { id: "panty", label: "Panties", gender: "Women" },
  { id: "print", label: "Printed", gender: "Women" },
  { id: "brief", label: "Briefs", gender: "Men" },
  { id: "trunk", label: "Trunks", gender: "Men" },
  { id: "top", label: "Vests & Tees", gender: "Men" },
];

const p = (
  id: string,
  category: ProductCategory,
  name: string,
  colour: string,
  hex: string,
  image: string,
  w: number,
  h: number,
): Product => ({
  id,
  category,
  name,
  colour,
  hex,
  image,
  w,
  h,
  gender: CATEGORIES.find((c) => c.id === category)!.gender,
});

